import java.io.BufferedReader
import java.io.BufferedWriter
import java.io.InputStreamReader
import java.io.OutputStreamWriter
import java.io.Reader
import java.io.Writer

const val INF = 1000000001

data class Pair(val first: Int, val second: Int)

fun sort(arr: IntArray, from: Int = 0, to: Int = arr.size): IntArray {
    if (to - from < 2) {
        return arr
    }
    var left = from
    val right = to - 1
    val pivot = from + (to - from) / 2

    val tmp = arr[pivot]
    arr[pivot] = arr[right]
    arr[right] = tmp

    for (i in from until to) {
        if (arr[i] < arr[right]) {
            val t = arr[i]
            arr[i] = arr[left]
            arr[left] = t
            left++
        }
    }

    val t2 = arr[left]
    arr[left] = arr[right]
    arr[right] = t2

    sort(arr, from, left)
    sort(arr, left + 1, to)
    return arr
}

fun check(n: Int): Boolean {
    var num = n
    var s = 0
    while (num > 0) {
        s += num % 10
        num /= 10
    }
    return s == 10
}

fun solution(reader: Reader, writer: Writer) {
    val br = reader as? BufferedReader ?: BufferedReader(reader)
    var k = br.readLine().trim().toInt()
    var i = 19
    while (k > 0) {
        if (check(i)) {
            k--
        }
        if (k == 0) {
            println(i)
            return
        }
        i++
    }
}

fun main() {
    val reader = BufferedReader(InputStreamReader(System.`in`), 1024 * 1024)
    val writer = BufferedWriter(OutputStreamWriter(System.out), 1024 * 1024)
    try {
        solution(reader, writer)
    } finally {
        writer.flush()
    }
}
